namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string CategorySlug { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Bruschetta", Category = "Appetizers", CategorySlug = "appetizers",
            Ingredients = ["Baguette", "Tomatoes", "Basil", "Garlic", "Olive oil"],
            Steps = ["Toast bread slices.", "Dice tomatoes and mix with basil and garlic.", "Top bread with tomato mixture and drizzle with olive oil."],
            AverageRating = 4.2, RatingCount = 5
        },
        new()
        {
            Id = 2, Title = "Stuffed Mushrooms", Category = "Appetizers", CategorySlug = "appetizers",
            Ingredients = ["Button mushrooms", "Cream cheese", "Garlic", "Parsley", "Breadcrumbs"],
            Steps = ["Remove mushroom stems.", "Mix cream cheese, garlic, and parsley.", "Fill caps and top with breadcrumbs.", "Bake at 375°F for 20 minutes."],
            AverageRating = 4.5, RatingCount = 8
        },
        new()
        {
            Id = 3, Title = "Spaghetti Carbonara", Category = "Main Courses", CategorySlug = "main-courses",
            Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Parmesan", "Black pepper"],
            Steps = ["Cook pasta al dente.", "Fry pancetta until crispy.", "Whisk eggs with Parmesan.", "Toss hot pasta with pancetta, then stir in egg mixture off heat."],
            AverageRating = 4.8, RatingCount = 12
        },
        new()
        {
            Id = 4, Title = "Chicken Stir Fry", Category = "Main Courses", CategorySlug = "main-courses",
            Ingredients = ["Chicken breast", "Bell peppers", "Soy sauce", "Ginger", "Rice"],
            Steps = ["Slice chicken and vegetables.", "Stir fry chicken until cooked.", "Add vegetables and soy sauce.", "Serve over steamed rice."],
            AverageRating = 4.0, RatingCount = 6
        },
        new()
        {
            Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts", CategorySlug = "desserts",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour"],
            Steps = ["Melt chocolate and butter together.", "Whisk eggs and sugar, fold in chocolate mixture.", "Add flour gently.", "Bake at 425°F for 12 minutes."],
            AverageRating = 4.9, RatingCount = 15
        },
        new()
        {
            Id = 6, Title = "Tiramisu", Category = "Desserts", CategorySlug = "desserts",
            Ingredients = ["Ladyfingers", "Mascarpone", "Espresso", "Cocoa powder", "Eggs"],
            Steps = ["Dip ladyfingers in espresso.", "Whisk mascarpone with egg yolks and sugar.", "Layer dipped ladyfingers and cream.", "Refrigerate 4 hours and dust with cocoa."],
            AverageRating = 4.7, RatingCount = 10
        }
    ];

    public List<Recipe> GetByCategory(string categorySlug)
    {
        return _recipes.Where(r => r.CategorySlug == categorySlug).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = totalStars / recipe.RatingCount;
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }
}

@page "/recipes/{CategorySlug}"
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>@CategoryName - RecipeHub</PageTitle>

<h1>@CategoryName</h1>

@if (_recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in _recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">
                            ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-link">← Back to Categories</a>

@code {
    [Parameter] public string CategorySlug { get; set; } = string.Empty;

    private List<Recipe> _recipes = [];
    private string CategoryName => CategorySlug.Replace("-", " ").ToUpperInvariant() switch
    {
        "APPETIZERS" => "Appetizers",
        "MAIN COURSES" => "Main Courses",
        "DESSERTS" => "Desserts",
        _ => CategorySlug
    };

    protected override void OnInitialized()
    {
        _recipes = RecipeService.GetByCategory(CategorySlug);
    }
}

@page "/recipe/{Id:int}"
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService

@if (_recipe is null)
{
    <PageTitle>Recipe Not Found - RecipeHub</PageTitle>
    <h1>Recipe Not Found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
}
else
{
    <PageTitle>@_recipe.Title - RecipeHub</PageTitle>

    <h1>@_recipe.Title</h1>
    <p class="text-muted">Category: @_recipe.Category</p>

    <h3>Ingredients</h3>
    <ul>
        @foreach (var ingredient in _recipe.Ingredients)
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in _recipe.Steps)
        {
            <li class="mb-2">@step</li>
        }
    </ol>

    <h3>Rating</h3>
    <p>⭐ @_recipe.AverageRating.ToString("F1") (@_recipe.RatingCount ratings)</p>

    <StarRating RecipeId="_recipe.Id" />

    <a href="/recipes/@_recipe.CategorySlug" class="btn btn-link mt-3">← Back to @_recipe.Category</a>
}

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? _recipe;

    protected override void OnInitialized()
    {
        _recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeHub.Services
@inject RecipeService RecipeService

<div class="my-3">
    <strong>Rate this recipe:</strong>
    <div class="d-inline-block ms-2" style="font-size: 1.5rem; cursor: pointer;">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span @onclick="() => SubmitRating(star)"
                  @onmouseover="() => _hovered = star"
                  @onmouseout="() => _hovered = 0"
                  class="@(star <= (_hovered > 0 ? _hovered : _selected) ? "text-warning" : "text-muted")">
                ★
            </span>
        }
    </div>
    @if (_submitted)
    {
        <span class="text-success ms-2">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int _hovered;
    private int _selected;
    private bool _submitted;

    private void SubmitRating(int stars)
    {
        _selected = stars;
        RecipeService.AddRating(RecipeId, stars);
        _submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        Your recipe "<strong>@_title</strong>" has been submitted successfully!
        <a href="/recipes/@_categorySlug">View category</a>
    </div>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" @bind-Value="_model.Title" class="form-control" />
            <ValidationMessage For="() => _model.Title" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" @bind-Value="_model.Category" class="form-select">
                <option value="">-- Select a category --</option>
                <option value="appetizers">Appetizers</option>
                <option value="main-courses">Main Courses</option>
                <option value="desserts">Desserts</option>
            </InputSelect>
            <ValidationMessage For="() => _model.Category" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" @bind-Value="_model.Ingredients" class="form-control" rows="5" />
            <ValidationMessage For="() => _model.Ingredients" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" @bind-Value="_model.Steps" class="form-control" rows="5" />
            <ValidationMessage For="() => _model.Steps" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeFormModel _model = new();
    private bool _submitted;
    private string _title = string.Empty;
    private string _categorySlug = string.Empty;

    private void HandleSubmit()
    {
        var categoryName = _model.Category switch
        {
            "appetizers" => "Appetizers",
            "main-courses" => "Main Courses",
            "desserts" => "Desserts",
            _ => _model.Category
        };

        var recipe = new Recipe
        {
            Title = _model.Title,
            Category = categoryName,
            CategorySlug = _model.Category,
            Ingredients = _model.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = _model.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList()
        };

        RecipeService.AddRecipe(recipe);
        _title = _model.Title;
        _categorySlug = _model.Category;
        _submitted = true;
    }
}

